import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Fused kernel: C = triu(A @ B) where A and B are upper triangular.
// Launch only the upper-triangular output tiles; a 1D block index is
// enumerated over the T*(T+1)/2 non-zero tiles, and blocks with a small
// linear id additionally clear one strictly-lower tile.
// Occupancy optimization: use 512 threads per CTA with a smaller 8x4
// per-thread fragment (32 accumulators instead of 64), halving register
// pressure. __launch_bounds__(512, 2) caps registers at 64/thread so two
// CTAs are resident per SM (50% occupancy instead of the register-limited
// 33%), hiding cp.async / shared-memory latency. Global->shared copies
// keep the proven 256-thread 16-byte cp.async vectorization (the upper
// half of the CTA is predicated off for copies only) and the 3-stage
// pipeline is unchanged.
template <class TA, class TB, class TC, class SA, class SB, class SC>
__global__ static void __launch_bounds__(512, 2)
triu_gemm_device(cute::Shape<int,int,int> shape_MNK,
                 TA const* A, SA dA,
                 TB const* B, SB dB,
                 TC      * C, SC dC)
{
  using namespace cute;
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  const int tiles_m = M / 128;
  const int tiles_n = N / 128;
  const int upper_tiles = tiles_m * (tiles_n + 1) / 2;
  const int lower_tiles = tiles_m * (tiles_n - 1) / 2;
  const int bid = blockIdx.x;
  // Map linear upper-tile id -> (bx, by) with bx <= by:
  // row bx contains (tiles_n - bx) upper tiles.
  int bx = 0;
  int rem = bid;
  while (rem >= tiles_n - bx) {
    rem -= tiles_n - bx;
    ++bx;
  }
  const int by = bx + rem;
  // Represent full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), dC); // (M,N)
  // Tile
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(bx, by, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});
  // Shared memory (double-buffered to pipeline global->shared loads)
  __shared__ alignas(16) TA smemA[3][128*12];
  __shared__ alignas(16) TB smemB[3][128*8];
  auto sA_layout = make_layout(make_shape(Int<128>{}, Int<8>{}), make_stride(Int<12>{}, Int<1>{}));
  auto sB_layout = make_layout(make_shape(Int<128>{}, Int<8>{}), make_stride(Int<1>{}, Int<128>{}));
  Tensor sA0 = make_tensor(make_smem_ptr(&smemA[0][0]), sA_layout);
  Tensor sA1 = make_tensor(make_smem_ptr(&smemA[1][0]), sA_layout);
  Tensor sA2 = make_tensor(make_smem_ptr(&smemA[2][0]), sA_layout);
  Tensor sB0 = make_tensor(make_smem_ptr(&smemB[0][0]), sB_layout);
  Tensor sB1 = make_tensor(make_smem_ptr(&smemB[1][0]), sB_layout);
  Tensor sB2 = make_tensor(make_smem_ptr(&smemB[2][0]), sB_layout);
  auto cpA = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<cute::uint128_t>, TA>{};
  auto cpB = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<cute::uint128_t>, TB>{};
  auto tiled_copy_A = make_tiled_copy(
      cpA,
      Layout<Shape<_128, _2>, Stride<_2, _1>>{},
      Layout<Shape<_1, _4>>{});
  auto tiled_copy_B = make_tiled_copy(
      cpB,
      Layout<Shape<_32, _8>, Stride<_1, _32>>{},
      Layout<Shape<_4, _1>>{});
  const int copy_tid = threadIdx.x & 255;
  auto thr_copy_A = tiled_copy_A.get_thread_slice(copy_tid);
  auto thr_copy_B = tiled_copy_B.get_thread_slice(copy_tid);
  Tensor tAgA  = thr_copy_A.partition_S(gA);
  Tensor tAsA0 = thr_copy_A.partition_D(sA0);
  Tensor tAsA1 = thr_copy_A.partition_D(sA1);
  Tensor tBgB  = thr_copy_B.partition_S(gB);
  Tensor tBsB0 = thr_copy_B.partition_D(sB0);
  Tensor tBsB1 = thr_copy_B.partition_D(sB1);
  Tensor tAsA2 = thr_copy_A.partition_D(sA2);
  Tensor tBsB2 = thr_copy_B.partition_D(sB2);
  auto tC = make_layout(make_shape(Int<16>{}, Int<32>{}));
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsA2 = local_partition(sA2, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB2 = local_partition(sB2, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC  = local_partition(gC,  tC, threadIdx.x, Step<_1,_1>{});
  Tensor cC   = make_identity_tensor(make_shape(Int<128>{}, Int<128>{}));
  Tensor tCcC = local_partition(cC, tC, threadIdx.x, Step<_1,_1>{});
  const int row0 = bx * 128;
  const int col0 = by * 128;
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  constexpr int k_tiles_per_m_tile = 128 / 8;
  constexpr int k_tiles_per_n_tile = 128 / 8;
  const int k_begin = bx * k_tiles_per_m_tile;
  const int k_end = (by + 1) * k_tiles_per_n_tile - 1;
  if (threadIdx.x < 256) {
    copy(tiled_copy_A, tAgA(_,_,_,k_begin), tAsA0);
    copy(tiled_copy_B, tBgB(_,_,_,k_begin), tBsB0);
  }
  cp_async_fence();
  if (k_begin < k_end) {
    if (threadIdx.x < 256) {
      copy(tiled_copy_A, tAgA(_,_,_,k_begin+1), tAsA1);
      copy(tiled_copy_B, tBgB(_,_,_,k_begin+1), tBsB1);
    }
    cp_async_fence();
  }
  int read_stage = 0;
  for (int k_tile = k_begin; k_tile <= k_end; ++k_tile) {
    if (k_tile < k_end) {
      cp_async_wait<1>();
    } else {
      cp_async_wait<0>();
    }
    __syncthreads();
    const int prefetch_tile = k_tile + 2;
    if (prefetch_tile <= k_end) {
      const int write_stage = (read_stage + 2) % 3;
      if (threadIdx.x < 256) {
        if (write_stage == 0) {
          copy(tiled_copy_A, tAgA(_,_,_,prefetch_tile), tAsA0);
          copy(tiled_copy_B, tBgB(_,_,_,prefetch_tile), tBsB0);
        } else if (write_stage == 1) {
          copy(tiled_copy_A, tAgA(_,_,_,prefetch_tile), tAsA1);
          copy(tiled_copy_B, tBgB(_,_,_,prefetch_tile), tBsB1);
        } else {
          copy(tiled_copy_A, tAgA(_,_,_,prefetch_tile), tAsA2);
          copy(tiled_copy_B, tBgB(_,_,_,prefetch_tile), tBsB2);
        }
      }
      cp_async_fence();
    }
    if (read_stage == 0) {
      gemm(tCsA0, tCsB0, tCrC);
    } else if (read_stage == 1) {
      gemm(tCsA1, tCsB1, tCrC);
    } else {
      gemm(tCsA2, tCsB2, tCrC);
    }
    __syncthreads();
    read_stage = (read_stage + 1) % 3;
  }
  for (int i = 0; i < size(tCrC); ++i) {
    auto coord = tCcC(i);
    int r = row0 + get<0>(coord);
    int c = col0 + get<1>(coord);
    tCgC(i) = (r <= c) ? tCrC(i) : TC(0);
  }
  // Clear one strictly-lower tile per upper CTA until all lower tiles are
  // initialized. Enumerate lower tiles row-major over (row_tile, col_tile),
  // where row_tile > col_tile.
  if (bid < lower_tiles) {
    int row_tile = 1;
    int col_tile = bid;
    while (col_tile >= row_tile) {
      col_tile -= row_tile;
      ++row_tile;
    }
    // First coordinate is M/row, second is N/column.
    auto zcoord = make_coord(row_tile, col_tile, _);
    Tensor gZ = local_tile(mC, cta_tiler, zcoord, Step<_1,_1,X>{});
    Tensor tCgZ = local_partition(gZ, tC, threadIdx.x, Step<_1,_1>{});
    for (int i = 0; i < size(tCgZ); ++i) {
      tCgZ(i) = TC(0);
    }
  }
}

// Host wrapper
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal A.size(1)");
  TORCH_CHECK(M == K && K == N,
              "triu_matmul expects square triangular matrices");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "This kernel expects M multiple of 128, N multiple of 128 and K multiple of 8");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  auto is_16B_aligned = [](const void* p) {
    return (reinterpret_cast<uintptr_t>(p) & 0xF) == 0;
  };
  TORCH_CHECK(is_16B_aligned(ptrA), "A must be 16-byte aligned");
  TORCH_CHECK(is_16B_aligned(ptrB), "B must be 16-byte aligned");
  TORCH_CHECK(is_16B_aligned(ptrC), "C must be 16-byte aligned");
  // Row-major A (M,K): stride (K, 1)
  auto dA = make_stride(K, Int<1>{});
  // Row-major B (K,N) viewed as (N,K): stride (1, N)
  auto dB = make_stride(Int<1>{}, N);
  // Row-major C (M,N): stride (N, 1)
  auto dC = make_stride(N, Int<1>{});
  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(512);
  const int tiles_m = M / 128;
  const int tiles_n = N / 128;
  dim3 dimGrid(tiles_m * (tiles_n + 1) / 2);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triu_gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE triu_gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

triu_matmul_ext = load_inline(
    name="cute_triu_matmul_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs matrix multiplication (C = A * B) for upper
    triangular matrices, computed by a single fused CUTE CUDA kernel that
    computes triu(A @ B) directly, exploiting the triangular structure to
    skip zero tiles and zero K-blocks.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = triu_matmul_ext

    def forward(self, A, B):
        return self._ext.triu_matmul(A, B)

